## 3. Result-Generation Logic (form data → recommendation)

The actual recommendation logic is defined inline in the Compass page as `evaluate(inputs)` (there is no separate `peyroniesLogic.ts`). Verbatim below.

Source: `client/src/pages/PeyroniesCompass.tsx`

```typescript
type DiseasePhase = "acute" | "chronic";
type CurvatureDirection = "dorsal" | "ventral" | "lateral" | "complex";
type ERDysfunction = "none" | "mild" | "moderate" | "severe";

interface PDInputs {
  diseasePhase: DiseasePhase;
  curvatureDegrees: number;
  curvatureDirection: CurvatureDirection;
  hinge: boolean;
  hourglass: boolean;
  penisShorteningCm: number;
  erDysfunction: ERDysfunction;
  iief5Score: number;
  pdeInhibitorResponse: boolean;
  priorCollagenaseInjections: boolean;
  priorSurgery: boolean;
  stableMonths: number;
  sexuallyActive: boolean;
  partnerConsent: boolean;
}

const defaultInputs: PDInputs = {
  diseasePhase: "chronic", curvatureDegrees: 0, curvatureDirection: "dorsal",
  hinge: false, hourglass: false, penisShorteningCm: 0, erDysfunction: "none",
  iief5Score: 0, pdeInhibitorResponse: true, priorCollagenaseInjections: false,
  priorSurgery: false, stableMonths: 0, sexuallyActive: true, partnerConsent: false,
};

function evaluate(inputs: PDInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Nehra A, et al. Peyronie's Disease: AUA Guideline. J Urol. 2015;194(3):745-753.",
    "Hatzimouratidis K, et al. EAU Guidelines on Penile Curvature. Eur Urol. 2012;62(3):543-552.",
    "Gelbard M, et al. Clinical efficacy, safety and tolerability of collagenase clostridium histolyticum for the treatment of Peyronie disease in 2 large double-blind, randomized, placebo controlled phase 3 studies. J Urol. 2013;190(1):199-207.",
    "Levine LA, Burnett AL. Standard operating procedures for Peyronie's disease. J Sex Med. 2013;10(1):230-244.",
    "Coyne KS, et al. The validation of the Peyronie's Disease Questionnaire. J Sex Med. 2015;12(4):1005-1016.",
  ];

  let recommendation = "not_indicated";
  let procedure = "";
  let cor = "I";
  let loe = "B";

  if (inputs.diseasePhase === "acute") {
    recommendation = "not_indicated";
    procedure = "Non-surgical management — disease not yet stable";
    cor = "III"; loe = "C";
    warnings.push("Acute phase (active disease): surgery is contraindicated until curvature has been stable for ≥12 months.");
    rationale.push("AUA Guideline: surgery should only be performed after disease stability for ≥12 months (no change in curvature, pain resolution).");
  } else if (inputs.stableMonths < 12) {
    recommendation = "not_indicated";
    procedure = "Continue observation — await 12 months of stability";
    warnings.push(`Disease stable for only ${inputs.stableMonths} months. AUA requires ≥12 months of stability before surgical correction.`);
  } else if (inputs.curvatureDegrees < 30) {
    recommendation = "consider";
    procedure = "Observation or non-surgical management";
    cor = "IIb"; loe = "C";
    rationale.push("Curvature <30°: may not significantly impair sexual function. Shared decision-making with patient.");
  } else {
    // Surgical candidate
    if (inputs.erDysfunction === "severe" || inputs.iief5Score < 11) {
      recommendation = "indicated";
      procedure = "Penile Prosthesis Implantation (IPP) with intraoperative modeling";
      cor = "I"; loe = "B";
      rationale.push("Severe ED + Peyronie's disease: penile prosthesis is the preferred surgical option — treats both ED and curvature simultaneously.");
      rationale.push("AUA Guideline: IPP with intraoperative modeling/plication is recommended for men with severe ED and Peyronie's disease.");
    } else if (inputs.curvatureDegrees <= 60 && !inputs.hinge && !inputs.hourglass && inputs.penisShorteningCm < 1) {
      recommendation = "indicated";
      procedure = "Plication (Nesbit/modified Nesbit) — shortening procedure";
      cor = "I"; loe = "B";
      rationale.push("Curvature ≤60°, no hinge/hourglass, minimal shortening: plication (Nesbit) is appropriate — simpler, lower complication rate.");
      rationale.push("Expected straightening: 85–95% success rate with plication for moderate curvature.");
    } else {
      recommendation = "indicated";
      procedure = "Plaque Incision/Excision with Grafting (Lue procedure)";
      cor = "I"; loe = "B";
      rationale.push("Curvature >60°, hinge/hourglass deformity, or significant shortening: grafting procedure is preferred to restore length and correct complex deformity.");
      warnings.push("Grafting procedures carry higher risk of post-operative ED (10–20%). Ensure adequate pre-operative erectile function.");
    }
  }

  if (inputs.hinge) warnings.push("Hinge deformity present: associated with higher risk of buckling and penetration difficulty; grafting procedure preferred.");
  if (inputs.hourglass) warnings.push("Hourglass deformity: complex correction required; refer to high-volume Peyronie's specialist.");
  if (!inputs.partnerConsent) warnings.push("Partner has not been counseled: AUA recommends partner involvement in surgical decision-making.");
  if (inputs.priorCollagenaseInjections && inputs.curvatureDegrees > 30) {
    rationale.push("Prior collagenase injections with residual curvature >30°: surgery is appropriate next step per AUA guidelines.");
  }

  return { recommendation, procedure, cor, loe, warnings, rationale, references };
}
